def is_isomorphic(graph, p):
    def create_edges(p, graph):
        edges = []
        for i, j in graph:
            if p[i-1] == j - 1:
                edges.append((i, j))
        return edges

    edges = create_edges(p, graph)
    sorted_edges = sorted(edges)
    mapping = {i+1: p[i+1] for i in range(len(p)-1)}
    for i, j in sorted_edges:
        if mapping[i] < mapping[j]:
            return False
    return True

def find_smallest_isomorphic(graph):
    for p in permutations(range(1, len(graph)+1)):
        if is_isomorphic(graph, p):
            return p
    return -1

