class LuckyNumberProcessor:
    def __init__(self, n, queries):
        self.n = n
        self.queries = queries
        self.lucky_digits = [4, 7]
        self.original_string = self.generate_initial_string()
        self.sorted_string = self.sort_lucky_digits(self.original_string)
        self.min_switch_positions = self.find_min_switch_positions()

    def generate_initial_string(self):
        string = ""
        while n:
            string += str(self.lucky_digits[n % 2])
            n //= 2
        return string

    def sort_lucky_digits(self, string):
        return ''.join(sorted(string, key=lambda x: self.lucky_digits.index(x)))

    def find_min_switch_positions(self):
        positions = []
        for pos in range(self.n):
            matches = self.get_lucky_length_matches(pos)
            for match in matches:
                positions.append(match)
        positions.sort()
        return positions

    def get_lucky_length_matches(self, position):
        match_ids = [position // self.n + 1, position % self.n + 1]
        if position < self.n - 1:
            match_ids.extend([self.n - position // self.n * 2, position % self.n + self.n])
        matches = [p for p in range(
            match_ids[0] * self.n * 2 + 1, match_ids[1] * self.n * 2) if self.is_lucky(match_ids[0] * self.n)]
        return matches

    def is_lucky(self, position):
        return ((position // (self.n * 2)) % 2 == 0 and (position % self.n) % 2 == 0) or ((position // (self.n * 2)) % 2 == 1 and (position % self.n) % 2 == 1)

    def process_queries(self):
