        """Computes nCr (fast computation method?)"""
        r = min(n-r, r)
        prod = 1
        for i in range(r, r+n)[::2]:
            prod = (prod * inv(i%2**20, r)) % 1000000007
            r -= 1
        return prod

    def nCc(n, m, N, sides):
        """Computes sum_{w=0}^m sum_{v=0}^N sum_{u=0}^{N-w} sum_{r=0}^N C(w, v-r+u) p_v*p_u mod N"""
        cur = (lookup[N-m-1][M-2] + lookup[N-m-1][M-1]) % 1000000007
        inc = 2
