                        inner = nC(n, w) * nC(r, w) % 1000000007
                        sideMul = nCc(N, v, side + sides, w-major_side)
                        ways += (inner * sideMul) % 1000000007
                        w = w + w2 + w + r + n - w2 - inc + n
    ways = 0
