from collections import defaultdict

def find_ancestor(a, b):
    path_a = []
    path_b = []

    while a != b:
        a = father[a].id
        path_a.append(a)

    while b != a:
        b = parent[b].id
        path_b.append(b)

    return a, tuple(path_a[::-1]), tuple(path_b[::-1])

def bit_xor(a, b):
    result = 0
    while a > 0 or b > 0:
        if a & 1:
            result |= b
        if b & 1:
            result |= a
        a >>= 1
        b >>= 1
    return result

def query(a, b):
    a, path_a, path_b = find_ancestor(a, b)
    xor_value = 0
    for i in path_a:
        xor_value ^= a
        a = father[i].id

    for i in path_b[::-1]:
        xor_value ^= b
        b = parent[i].id

    return xor_value

