def optimal_arrangement(n, regions):
    sheep_positions = {i: [] for i in range(1, n+1)}
    for l, r in regions:
        for inc in range(l, r+1):
            sheep_positions[inc].append(l)

    available = [(0, 0)]
    placed = [False] * n

    while available:
        start, end = available.pop(0)
        nodes = range(start, end+1)
        for sheep in nodes:
            for start, dp in sheep_positions[dp]:
                sheep_positions[dp].remove((start, dp))
                if dp == sheep:
                    continue
                if sheep not in sheep_positions[dp] and end + len(sheep_positions[dp]) not in sheep_positions[dp]:
                    sheep_positions[dp].append((end+1, sheep))
            placed[dp-1] = True
        if not any(placed):
            continue
        new_start, new_end = sheep_positions[end]
        if start < new_start:
            available.append((start, new_start))
        if new_end < end:
            available.append((new_end, end))

    answer = [None] * n
    for (start, end), sheep in sorted(sheep_positions.items()):
        sheep_start = (start, end-1)
        num_sheep = (len(sheep) + 1) // 2
        answer[num_sheep] = sheep_start[0]
        for (a, b), dp in sheep:
            sheep_positions[dp].remove((a, b))
            sheep_positions[dp].append(sheep_start[1] + num_sheep, dp)
        available.append((start, end-1))

    return ' '.join(map(str, answer))

