from fractions import Fraction

def find_heuristic_tree_size(n, costs):
    total_path_cost = 0
    max_path_cost = 0
    max_node = -1

    for u, v, c in costs:
        if u != v:
            total_path_cost += c
            max_path_cost = max(max_path_cost, c)
            if max_node != -1 and max(max_path_cost - c, 0, c) == max_path_cost - c:
                n -= 1

            if max_node == -1:
                max_node = u
            else:
                max_node = max(u, v)

    return Fraction(total_path_cost, n + 1), max_node

def get_tree_paths(n, root, parent, path_lengths, current_path):
    if current_path:
        path_lengths[root] = path_lengths[root] + 1
        return

    for child in range(n):
        if current_path is None or parent[child] != current_path:
            get_tree_paths(n, child, root, path_lengths, child)

def calculate_expected_cost(tree_size, fraction_tree_size, root_node):
    path_lengths = defaultdict(lambda: 1)
    get_tree_paths(n, root_node, -1, path_lengths, None)

    return int((traditional_cost * (tree_size - 1) + choice_cost) / fraction_tree_size, 9)

if __name__ == "__main__":
