        adjacency_list[u-1].add(v-1)
        adjacency_list[v-1].add(u-1)

    sorted_edges = sorted([tuple(sorted(e)) for e in edges])
    dp = OrderedDict()
    for i in range(n):
        if len(dp) == 0 or dp[sorted_edges[i][0]] != 0 or dp[sorted_edges[i][1]] != 0:
            dp[sorted_edges[i]] = 1
        for j in range(n):
            if j == sorted_edges[i][0] or j == sorted_edges[i][1]:
                continue
            if (j, sorted_edges[i][0]) in dp or (j, sorted_edges[i][1]) in dp:
                continue
            if j in dp.keys() or pos(j, sorted_edges[i][0]) + pos(sorted_edges[i][1], j) in dp.keys():
                continue
            dp[sorted_edges[i]] = 1
            break

    return dp

def pos(u, v):
