from typing import List
from functools import lru_cache

class MathOperations:
    @staticmethod
    def sum_mod(a: List[int], l: int, r: int, p: int) -> int:
        if l > r:
            return 0
        if r - l + 1 > p:
            raise ValueError("The sum exceeds the modulus")

        @lru_cache(None)
        def mod_add(x: int) -> int:
            return (a[x] + a[x - 1]) % p

        @lru_cache(None)
        def sum_m_mplus1(x: int) -> int:
            return mod_add(x) + mod_add(x + 1) - mod_add(x + p - 1)

        mod_sum = 0
        for i in range(l - 1, r):
            mod_sum += sum_m_mplus1(i)
        return mod_sum % p

    @staticmethod
    def mod_add(x: int, y: int, p: int) -> int:
        return (y - x) % p + p if y < x else y - x

    @staticmethod
    def solve(numbers: List[int], queries: List[List[int]], p: int) -> List[int]:
        sums = [0] * len(numbers)
        for i in range(len(numbers) - 1):
            MathOperations.mod_add(numbers[i], numbers[i + 1], p)
            sums[i] = numbers[i] % p

        result = []
        for l, r in queries:
            result.append(MathOperations.sum_mod(sums, l - 1, r, p))
        return result
