def prime_factors(n: int) -> List[int]:
    """Return prime factors of n."""
    factors = []
    for i in range(2, int(n ** 0.5) + 1):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return factors

def mod_inverse(m: int, modulo: int) -> int:
    """Return (m^-1) mod modulo."""
    for i in range(1, modulo):
        if (m * i) % modulo == 1:
