import math

def get_circle_intersection(circle1, circle2):
    # Get circle 1's radius
    a = math.sqrt(circle1[0]**2 + circle1[1]**2)
    radius_1 = circle1[2]
    # Circles does not intersect or touch each other, return intersection direction as is the circle 2's centre
    if a > circle2[2]: return (circle2[0], circle2[1], 0)
    xdiff = max(circle2[0] - circle1[0], circle2[0] + circle2[0] - circle1[0], 
                circle2[1] - circle1[1], circle2[1] + circle2[1] - circle1[1])
    ydiff = max(circle2[1] - circle1[1], circle2[1] + circle2[1] - circle1[1])
    po = (xdiff/a, ydiff/a)
    dist = math.sqrt(po[0]**2 + po[1]**2)
    theta = math.acos(po[0] / dist)
    if xdiff > dist:
        theta = 2 * math.pi - theta
    return (circle1[0] + xdiff, circle1[1] + ydiff, radius_1 - dist)

