def build_tree(edges):
    tree = defaultdict(list)
    n = len(edges)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)
    return tree, n

def find_path(tree, start, end, parent = None, path = []):
    path += [start]
    if start == end:
        return path
    for child in tree[start]:
        if child != parent:
            found = find_path(tree, child, end, start, path)
            if found:
                return found
    return path

def is_isomorphic(target_path, edge_pathes):
    for begin, end, *edges in edge_pathes:
        if target_path != find_path(tree, begin, end, parent = begin):
            return False
    return True

def construct_permutations(tree, depth, n, length, edges):
    if length == 0:
        return [[] for _ in range(n)]
    elif depth == 0:
        return [[i] for i in range(1, n + 1)]
    subsequences = construct_permutations(tree, depth - 1, n, length - 1,  edges)
    for s in subsequences:
        edge_paths = [()]
        for i in range(len(s)):
            edge_paths += [(".".join(s[:i] + [x])) for x in edges[i]]
        if is_isomorphic(s, edge_paths):
            s_undos = []
            for e in edges:
                s_undos += [(e[0], s[-1])]
            yield [x for x in s] + [x[1] for x in s_undos]
    return

