def is_isomorphic(graph: List[List[int]]) -> bool:
    # Check if the graph is a tree using depth-first search
    def is_tree(node=1, parent=-1):
        visited = set([node])
        stack = [node]
        while stack:
            current = stack.pop()
            for neighbor in graph[current]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    return False
                visited.add(neighbor)
                stack.append(neighbor)
        return True

    vertex_count = len(graph)
    possible = permutations(range(1, vertex_count + 1))
