        parent = None
        current = 1
        edges = []
        is_isomorphic = True
        for vertex in perm:
            if vertex in edges:
                continue
            if current == vertex:
                parent = current
                current += 1
            else:
                edges.append(current)
                current = vertex
            if parent:
                if parent in edges and current in edges:
                    is_isomorphic = False
        if is_isomorphic:
            if not best or len(perm) < len(best):
                best = perm
    return best or [-1]

