import heapq

def find_smallest_inversions(arr):
    arr = [(-val, ind) for ind, val in enumerate(arr)]
    heapq.heapify(arr)
    smallest_inversions = []
    while len(arr) > 0:
        smallest_val, index = heapq.heappop(arr)
        if index >= 0:
            smallest_inversions.append(index)
            heapq.heappush(arr, (1 - smallest_val, index -1))
            heapq.heappush(arr, (1 - smallest_val, index + 1))
        else:
            heapq.heappush(arr, (1 - smallest_val, index -1))
            heapq.heappush(arr, (1 - smallest_val, index + 1))
    return smallest_inversions

