            if current_balan[i] + N - h[i] <= 0:
                continue
            new = []
            for j, ve in enumerate(valid):
                if current_balan[j] + ve <= N-1:
                    new.append(p[j])
                    for k in range(i, N):
                        if current_balan[p[j]] - h[k] - 1 > 0:
                            current_balan[k] -= (current_balan[p[j]] - h[k] - 1)
            if new and is_possible(dp, h):
                valid = new

    return min(dp)
