import math

def is_convex_polygon(polygon):
    n = len(polygon)
    for i in range(n):
        a = math.atan2(polygon[i+1][1]-polygon[i][1], polygon[i+1][0]-polygon[i][0])
        b = math.atan2(polygon[(i+1)%(n-1)+1][1]-polygon[i][1], polygon[(i+1)%(n-1)+1][0]-polygon[i][0])
        if a - b < -math.pi / 2 or a - b > math.pi / 2:
            return False
    return True

def min_speed(n, points):
    if not is_convex_polygon(points):
        return float('inf')

    x_min, y_min = min(p[0] for p in points), min(p[1] for p in points)
    x_max, y_max = max(p[0] for p in points), max(p[1] for p in points)
    h = points[-1][1]

    if (x_min, y_min) == (x_max, y_max) or (x_min, y_max) == (x_max, y_min) or (x_min, y_min) == (x_min, 0) or (x_min, y_min) == (x_min, h) or (x_min, y_max) == (x_min, h):
        return float('inf')

    points += [points[0]]  # Close the polygon

    phi = math.pi / 2
    ratio = h / max(x_max, x_min + 10**18)

    theta_given = math.pi - phi
    theta_total = 0
    for i in range(n):
        x = points[i][0]
        y = points[i][1]

        if x < x_min + 10**18 and y < 0:
            theta_total += math.atan(x / (-10**18)) - phi
        elif x - x_min > 10**18 and y > 0:
            theta_total += math.atan((x - x_min) / y) + phi
        elif x < x_min + 10**18 and y > 0:
            theta_total += math.atan(x / (-10**18)) + phi
        elif x - x_min > 10**18 and y < 0:
            theta_total += phi + math.atan((x - x_min) / (-y))

        if x > x_max - 10**18 and y > 0:
            theta_total -= math.atan((x_max - x) / y) - (phi + theta_given + math.pi)
        elif x - x_max < -10**18 and y < 0:
            theta_total -= math.atan(x / (x_max - x)) + (phi + theta_given - math.pi)

    theta_total = theta_total / 2

    num_steps_per_peri = int(2 * math.pi / ratio)
    v_min = 2 * h / (2 * math.pi / ratio + num_steps_per_peri * phi)
    lowest_minimum = float('inf')
    for i in range(1, n):
        v_per_range = 2 * math.sin(theta_total / num_steps_per_peri) / \
            abs(points[i][0] - points[(i-1) % n][0])

        lowest_minimum = min(lowest_minimum, v_per_range)
    return lowest_minimum
