from collections import defaultdict

def calculate_expected_cost(n, friends, cost_matrix):
    # Build the adjacency list from the graph and cost matrix
    graph = defaultdict(dict)
    for u, v, c in friends:
        graph[u][v] = c
        graph[v][u] = c

    # Function to perform DFS and calculate expected cost
    def dfs(start, visited):
        visited.add(start)
        max_cost = 0
        for neighbor in graph[start]:
            if neighbor not in visited:
                if not graph[start][neighbor] or dfs(neighbor, visited):
                    max_cost = (graph[start][neighbor] * max(visited), max_cost + graph[start][neighbor]) or (dfs(neighbor, visited) * max_length, max_cost)
        if not max_cost[1]:
            max_cost = (max_length, max_cost[1])
        return max_cost

    max_length, expected_cost_map = dfs(0, set())

    # Calculate the probability of not being able to reach any friend in one day
    can_visit_time = 1
    for friend in range(n):
        if friend != 0:
            c = cost_matrix[friend][0]
            visited = frozenset([friend])
            index = dfs(friend, visited)[1]
            min_c = min(graph[0][friend] - cost_matrix[friend][0] + index * c, max_length - index * c)
            if min_c > expected_cost_map[friend]:
                can_visit_time = (c + min_c) // (c + cost_matrix[friend][0]) * index
            elif min_c < expected_cost_map[friend]:
                can_visit_time = (c + min_c) // expected_cost_map[friend] * index

    result = sum(expected_cost / can_visit_time for friend, expected_cost in expected_cost_map.items())

    return int(result)

