    l = 1
    r = 1
    cur_val = 0
    result = []
    found = False
    while l <= len(string):
        if l == r and string[l-1] == '4':
            found = True
            result.append('`')
            cur_val += 1
        if string[l-1] == '`':
            cur_val -= 1
        if string[l-1] == ':' and cur_val != 0:
