            cur_val = 0
        elif string[l-1] == '`' and len(result) > 1 and result[-1] == '`':
            result.pop()
        elif cur_val > 0 and result[-1] == '`' and l == r:
            result.append(':')
            r += 1
            cur_val = 0
        else:
            result.append(string[l-1])
            if string[l-1] == '7':
                l = r
            else:
                l += 1
        r += 1
