from itertools import permutations
from collections import defaultdict

def is_isomorphic(tree, permutation):
    graph = defaultdict(set)
    for u, v in tree:
        graph[u].add(v)
    visited = set()
    for u in graph:
        children = sorted(graph[u], key=permutation.index)
        for i in range(len(children) - 1):
            if children[i + 1] not in graph[children[i]]:
                return False
    for u in graph:
        if u not in visited:
            stack = [u]
            visited.add(u)
            while stack:
                current = stack.pop()
                for child in graph[current]:
                    if child not in visited:
                        stack.append(child)
                        visited.add(child)
    return True

def find_smallest_permutation(graph):
    for perm in permutations(range(1, len(graph) + 1)):
        if is_isomorphic(graph, perm):
            return perm
    return -1

